txn_record: dict
header_status = ""
state_status = ""
txn_status = ""
checkpoint: dict | None = None
stored: dict | None = None
txn_header: dict | None = None
txn_state: dict | None = None
try:
    with _checkpoint_lock(path):
        # Read each file independently: one invalid target must not
        # hide the standing of the other two, and nothing is rolled
        # forward or cleaned up.
        try:
            header_status, checkpoint = _audit_header_target(path)
        except _CheckpointError:
            return {"ok": False, "error": ERR_IO}
        try:
            state_status, stored = _audit_state_target(path)
        except _CheckpointError:
            return {"ok": False, "error": ERR_IO}
        try:
            txn_status, txn_header, txn_state = _audit_transaction(path)
        except _CheckpointError:
            return {"ok": False, "error": ERR_IO}

        if header_status == AUDIT_TARGET_VALID:
            assert checkpoint is not None
            header_record = {
                "status": AUDIT_TARGET_VALID,
                "generation": checkpoint["generation"],
                "tip": {
                    key: checkpoint["tip"][key] for key in HEADER_TIP_KEYS
                },
                "finalized": {
                    key: checkpoint["finalized"][key]
                    for key in HEADER_ANCHOR_KEYS
                },
            }
        else:
            header_record = {
                "status": header_status,
                "generation": None,
                "tip": None,
                "finalized": None,
            }

        if state_status == AUDIT_TARGET_VALID:
            assert stored is not None
            state_record = {
                "status": AUDIT_TARGET_VALID,
                "generation": stored["generation"],
                "account": stored["account"],
                "anchor": {
                    key: stored["anchor"][key]
                    for key in STATE_ANCHOR_ANCHOR_KEYS
                },
            }
        else:
            state_record = {
                "status": state_status,
                "generation": None,
                "account": None,
                "anchor": None,
            }

        if txn_status == AUDIT_TXN_VALID:
            assert txn_header is not None and txn_state is not None
            txn_record = {
                "status": AUDIT_TXN_VALID,
                "header_generation": txn_header["generation"],
                "state_generation": txn_state["generation"],
            }
        else:
            txn_record = {
                "status": txn_status,
                "header_generation": None,
                "state_generation": None,
            }
except OSError:
    # Defensive: a lock or filesystem surprise must report rather
    # than crash the auditing process; no bytes were changed.
    return {"ok": False, "error": ERR_IO}
except Exception:
    # Defensive: structurally unforeseeable inputs must report rather
    # than crash the caller.
    return {"ok": False, "error": ERR_IO}

# Overall classification in the contract's fixed decision order.
if (
    header_status == AUDIT_TARGET_MISSING
    and state_status == AUDIT_TARGET_MISSING
    and txn_status == AUDIT_TXN_ABSENT
):
    overall = AUDIT_STATUS_EMPTY
elif txn_status == AUDIT_TXN_VALID:
    overall = AUDIT_STATUS_RECOVERABLE
elif txn_status == AUDIT_TXN_INVALID:
    overall = AUDIT_STATUS_CORRUPT
elif header_status != AUDIT_TARGET_VALID or state_status != AUDIT_TARGET_VALID:
    # No journal: one target missing (an unpaired half) is a split;
    # an invalid stored file is corruption.
    if AUDIT_TARGET_INVALID in (header_status, state_status):
        overall = AUDIT_STATUS_CORRUPT
    else:
        overall = AUDIT_STATUS_SPLIT
else:
    # Both stored targets valid and no journal: consistent exactly
    # when the state anchor is bound to the header finalized boundary.
    assert checkpoint is not None and stored is not None
    finalized = checkpoint["finalized"]
    anchor = stored["anchor"]
    bound = (
        anchor["height"] == finalized["height"]
        and anchor["block_hash"] == finalized["block_hash"]
    )
    overall = AUDIT_STATUS_CONSISTENT if bound else AUDIT_STATUS_SPLIT

return {
    "ok": True,
    "status": overall,
    "header": header_record,
    "state": state_record,
    "transaction": txn_record,
}

"""Command line interface: send, tx, mine, block, account, proof, proofs,
state-root,
state-proof, confirm, rollback, status, candidates, chain, adopt, export,
index, sync, sync-range, sync-attested, sync-range-attested, syncs,
sync-history, sync-export, sync-range-export, chain-range,
audit, audit-export, trust
(add/rotate/revoke/export/allowlist-add/allowlist-remove) and offline
verify/audit-verify/consistency and offline verify-range/verify-range-batch
subcommands, the receipt-proofs-audit batch audit subcommand, plus the
offline checkpoint-history history-trust,
history-export and header-locators subcommands.

The CLI talks to a running ledger server over HTTP and prints each response as
a single line of JSON with exactly the same field names as the HTTP API.

Signing a transaction locally is supported through ``send --signing-key``;
the key may be 32 raw hex bytes or ``@/path/to/ed25519-key.pem``. An already
produced signature can be passed instead with ``--from/--signature``. The
``candidates`` subcommand takes the candidate fork's block array (or a
``{"blocks": [...]}`` object) as a single JSON argument.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import sys
import urllib.error
import urllib.parse
import urllib.request
from typing import Any

from . import crypto

DEFAULT_BASE_URL = os.environ.get("LEDGER_BASE_URL", "http://127.0.0.1:8080")


# -- HTTP helpers ------------------------------------------------------------


def _request(
    method: str, url: str, payload: dict | None, sort_keys: bool = True
) -> tuple[int, dict]:
    data = None
    headers = {"Accept": "application/json"}
    if payload is not None:
        data = json.dumps(payload, sort_keys=sort_keys).encode("utf-8")
        headers["Content-Type"] = "application/json"
    request = urllib.request.Request(url, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(request) as response:
            return response.status, json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        try:
            body = json.loads(exc.read().decode("utf-8"))
        except (ValueError, UnicodeDecodeError):
            body = {"error": exc.reason}
        return exc.code, body
    except (urllib.error.URLError, OSError) as exc:
        return 0, {"error": f"cannot reach ledger server: {exc}"}


def _emit(status: int, body: dict, sort_keys: bool = True) -> int:
    print(json.dumps(body, sort_keys=sort_keys, ensure_ascii=False))
    # 2xx responses are success; anything else (incl. connection failure) is 1.
    return 0 if 200 <= status < 300 else 1


# -- signing key handling ----------------------------------------------------


def _load_signing_key(spec: str):
    """Load an Ed25519 private key from raw hex or an ``@file`` (hex or PEM)."""
    from cryptography.hazmat.primitives import serialization

    if spec.startswith("@"):
        with open(spec[1:], "rb") as fh:
            material = fh.read()
    else:
        material = spec.encode("ascii")
    stripped = material.strip()
    if stripped.startswith(b"-----BEGIN"):
        key = serialization.load_pem_private_key(stripped, password=None)
    else:
        raw = bytes.fromhex(stripped.decode("ascii"))
        if len(raw) != 32:
            raise ValueError("signing key must be 32 raw bytes (64 hex chars)")
        from cryptography.hazmat.primitives.asymmetric.ed25519 import (
            Ed25519PrivateKey,
        )

        key = Ed25519PrivateKey.from_private_bytes(raw)
    from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey

    if not isinstance(key, Ed25519PrivateKey):
        raise ValueError("signing key is not an Ed25519 private key")
    return key


def _public_key_hex(key) -> str:
    from cryptography.hazmat.primitives import serialization

    return key.public_key().public_bytes(
        serialization.Encoding.Raw, serialization.PublicFormat.Raw
    ).hex()


# -- subcommands -------------------------------------------------------------


def cmd_send(args: argparse.Namespace) -> int:
    if args.signing_key:
        try:
            key = _load_signing_key(args.signing_key)
        except (ValueError, OSError, TypeError) as exc:
            return _emit(400, {"error": f"invalid signing key: {exc}"})
        sender = _public_key_hex(key)
        message = crypto.canonical_message(sender, args.to, args.amount)
        signature = key.sign(message).hex()
    else:
        if not args.sender or not args.signature:
            return _emit(
                400,
                {"error": "provide either --signing-key or both --from and --signature"},
            )
        sender, signature = args.sender, args.signature

    payload = {
        "from": sender,
        "to": args.to,
        "amount": args.amount,
        "signature": signature,
    }
    status, body = _request("POST", f"{args.base_url}/v1/transactions", payload)
    return _emit(status, body)


def cmd_mine(args: argparse.Namespace) -> int:
    status, body = _request("POST", f"{args.base_url}/v1/blocks", {})
    return _emit(status, body)


def cmd_block(args: argparse.Namespace) -> int:
    status, body = _request(
        "GET", f"{args.base_url}/v1/blocks/{args.height}", None
    )
    return _emit(status, body)


def cmd_tx(args: argparse.Namespace) -> int:
    quoted = urllib.parse.quote(args.tx_id, safe="")
    status, body = _request(
        "GET", f"{args.base_url}/v1/transactions/{quoted}", None
    )
    return _emit(status, body)


def cmd_account(args: argparse.Namespace) -> int:
    quoted = urllib.parse.quote(args.account, safe="")
    status, body = _request(
        "GET", f"{args.base_url}/v1/accounts/{quoted}", None
    )
    return _emit(status, body)


def cmd_state_root(args: argparse.Namespace) -> int:
    if args.height is None:
        url = f"{args.base_url}/v1/state/root"
    else:
        url = f"{args.base_url}/v1/state/root/{urllib.parse.quote(args.height, safe='')}"
    status, body = _request("GET", url, None)
    return _emit(status, body)


def cmd_state_proof(args: argparse.Namespace) -> int:
    quoted = urllib.parse.quote(args.account, safe="")
    url = f"{args.base_url}/v1/accounts/{quoted}/proof"
    if args.height is not None:
        url = f"{url}?height={urllib.parse.quote(args.height, safe='')}"
    status, body = _request("GET", url, None)
    return _emit(status, body)


def cmd_proof(args: argparse.Namespace) -> int:
    status, body = _request(
        "GET", f"{args.base_url}/v1/blocks/{args.height}/proof/{args.tx_id}", None
    )
    return _emit(status, body)


def cmd_proofs(args: argparse.Namespace) -> int:
    # Batch Merkle proofs: POST the requested ids verbatim; the server applies
    # the strict non-empty/distinct/64-lowercase-hex validation (400 on error).
    # The success document has a contract-fixed key order, so it is printed in
    # insertion order rather than alphabetically (error bodies are single-key).
    payload = {"tx_ids": args.tx_ids}
    status, body = _request(
        "POST", f"{args.base_url}/v1/blocks/{args.height}/proofs", payload
    )
    return _emit(status, body, sort_keys=False)


def cmd_confirm(args: argparse.Namespace) -> int:
    status, body = _request(
        "POST", f"{args.base_url}/v1/blocks/{args.height}/confirm", {}
    )
    return _emit(status, body)


def cmd_rollback(args: argparse.Namespace) -> int:
    status, body = _request(
        "POST", f"{args.base_url}/v1/blocks/{args.height}/rollback", {}
    )
    return _emit(status, body)


def cmd_status(args: argparse.Namespace) -> int:
    status, body = _request(
        "GET", f"{args.base_url}/v1/blocks/{args.height}/status", None
    )
    return _emit(status, body)


def cmd_candidates(args: argparse.Namespace) -> int:
    try:
        payload = json.loads(args.blocks_json)
    except (ValueError, TypeError) as exc:
        return _emit(400, {"error": f"invalid JSON payload: {exc}"})
    # Accept either the bare blocks array or the full {"blocks": [...]} object.
    body = {"blocks": payload} if isinstance(payload, list) else payload
    status, resp = _request(
        "POST", f"{args.base_url}/v1/forks/candidates", body
    )
    return _emit(status, resp)


def cmd_chain(args: argparse.Namespace) -> int:
    status, body = _request("GET", f"{args.base_url}/v1/chain", None)
    return _emit(status, body)


def cmd_adopt(args: argparse.Namespace) -> int:
    quoted = urllib.parse.quote(args.tip_hash, safe="")
    status, body = _request(
        "POST", f"{args.base_url}/v1/forks/{quoted}/adopt", {}
    )
    return _emit(status, body)


def cmd_export(args: argparse.Namespace) -> int:
    quoted = urllib.parse.quote(args.tip_hash, safe="")
    status, body = _request(
        "GET", f"{args.base_url}/v1/forks/{quoted}/export", None
    )
    return _emit(status, body)


def cmd_sync(args: argparse.Namespace) -> int:
    try:
        candidate = json.loads(args.candidate_json)
    except (ValueError, TypeError) as exc:
        return _emit(400, {"error": f"invalid JSON candidate: {exc}"})
    # Accept the bare blocks array or any export-format object verbatim.
    if isinstance(candidate, list):
        candidate = {"blocks": candidate}
    payload = {
        "source": args.source,
        "request_id": args.request_id,
        "expires_at": args.expires_at,
        "candidate": candidate,
    }
    status, body = _request("POST", f"{args.base_url}/v1/forks/sync", payload)
    return _emit(status, body)


def cmd_syncs(args: argparse.Namespace) -> int:
    filters = {
        "source": args.source,
        "mode": args.mode,
        "min_height": args.min_height,
        "max_height": args.max_height,
        "cursor": args.cursor,
        "limit": args.limit,
    }
    query = urllib.parse.urlencode(
        {key: value for key, value in filters.items() if value is not None}
    )
    url = f"{args.base_url}/v1/forks/sync"
    if query:
        url = f"{url}?{query}"
    status, body = _request("GET", url, None)
    return _emit(status, body)


def cmd_sync_history(args: argparse.Namespace) -> int:
    filters = {
        "source": args.source,
        "tip_hash": args.tip_hash,
        "kind": args.kind,
        "mode": args.mode,
        "min_height": args.min_height,
        "max_height": args.max_height,
        "cursor": args.cursor,
        "limit": args.limit,
    }
    query = urllib.parse.urlencode(
        {key: value for key, value in filters.items() if value is not None}
    )
    url = f"{args.base_url}/v1/forks/sync/history"
    if query:
        url = f"{url}?{query}"
    status, body = _request("GET", url, None)
    return _emit(status, body)


def cmd_sync_export(args: argparse.Namespace) -> int:
    # Export one received sync candidate by its idempotency key. The success
    # document has a contract-fixed key order, so it is printed in insertion
    # order rather than alphabetically (error bodies are single-key).
    query = urllib.parse.urlencode(
        {
            "source": args.source,
            "request_id": args.request_id,
            "mode": args.mode,
        }
    )
    status, body = _request(
        "GET", f"{args.base_url}/v1/forks/sync/export?{query}", None
    )
    return _emit(status, body, sort_keys=False)


def cmd_sync_range_export(args: argparse.Namespace) -> int:
    # Export one received incremental range delivery by its idempotency key.
    # The success document (source, request_id, mode, expires_at, anchor,
    # blocks, tip, attestation) has a contract-fixed key order, so it is
    # printed in insertion order rather than alphabetically (error bodies are
    # single-key).
    query = urllib.parse.urlencode(
        {
            "source": args.source,
            "request_id": args.request_id,
            "mode": args.mode,
        }
    )
    status, body = _request(
        "GET", f"{args.base_url}/v1/forks/sync/range/export?{query}", None
    )
    return _emit(status, body, sort_keys=False)


def cmd_chain_range(args: argparse.Namespace) -> int:
    filters = {
        "after_height": args.after_height,
        "after_hash": args.after_hash,
        "limit": args.limit,
    }
    query = urllib.parse.urlencode(
        {key: value for key, value in filters.items() if value is not None}
    )
    url = f"{args.base_url}/v1/chain/range"
    if query:
        url = f"{url}?{query}"
    status, body = _request("GET", url, None)
    return _emit(status, body)


def cmd_sync_range(args: argparse.Namespace) -> int:
    try:
        if args.range_json == "-":
            document = json.loads(sys.stdin.read())
        else:
            document = json.loads(args.range_json)
    except (ValueError, TypeError) as exc:
        return _emit(400, {"error": f"invalid JSON range document: {exc}"})
    # The range document is {"anchor", "blocks"[, "tip"]}; a GET
    # /v1/chain/range page may be piped verbatim (its extra canonical/
    # next_height fields are ignored).
    if not isinstance(document, dict):
        return _emit(400, {"error": "range document must be a JSON object"})
    anchor = document.get("anchor")
    blocks = document.get("blocks")
    if not isinstance(anchor, dict) or not isinstance(blocks, list):
        return _emit(
            400, {"error": "range document must contain an anchor object and a blocks list"}
        )
    payload = {
        "source": args.source,
        "request_id": args.request_id,
        "expires_at": args.expires_at,
        "anchor": anchor,
        "blocks": blocks,
    }
    tip = document.get("tip")
    if tip is None and blocks:
        # Derive the tip summary from the final delivered block so a plain
        # range page (which carries no tip) can be pushed verbatim.
        last = blocks[-1]
        if isinstance(last, dict):
            anchor_height = anchor.get("height")
            length = (
                anchor_height + 1 + len(blocks)
                if isinstance(anchor_height, int) and not isinstance(anchor_height, bool)
                else None
            )
            tip = {
                "tip_hash": last.get("block_hash"),
                "height": last.get("height"),
                "length": length,
                "status": last.get("status"),
            }
    if tip is not None:
        payload["tip"] = tip
    status, body = _request("POST", f"{args.base_url}/v1/forks/sync/range", payload)
    return _emit(status, body)


def cmd_sync_attested(args: argparse.Namespace) -> int:
    try:
        if args.candidate_json == "-":
            candidate = json.loads(sys.stdin.read())
        else:
            candidate = json.loads(args.candidate_json)
    except (ValueError, TypeError) as exc:
        return _emit(400, {"error": f"invalid JSON candidate: {exc}"})
    # Preserve the candidate's original form (export object, {"blocks": [...]}
    # wrapper or a bare block array): the signature is over the canonical
    # message embedding exactly that parsed value.
    if not isinstance(candidate, (dict, list)):
        return _emit(400, {"error": "candidate must be a JSON object or array"})
    document = {
        "domain": "ledger-sync-v1",
        "source": args.source,
        "request_id": args.request_id,
        "expires_at": args.expires_at,
        "candidate": candidate,
    }
    message = json.dumps(
        document, sort_keys=True, ensure_ascii=False, separators=(",", ":")
    ).encode("utf-8")
    # Sign the raw 32-byte SHA-256 digest with the 64-lowercase-hex Ed25519
    # seed; the result is a 128-lowercase-hex signature.
    signature = crypto.sign_message(
        args.signing_key, hashlib.sha256(message).digest()
    )
    if signature is None:
        return _emit(400, {"error": "signing key must be 64 lowercase hex characters"})
    payload = {
        "source": args.source,
        "request_id": args.request_id,
        "expires_at": args.expires_at,
        "candidate": candidate,
        "signature": signature,
    }
    status, body = _request(
        "POST", f"{args.base_url}/v1/forks/sync/attested", payload
    )
    return _emit(status, body)


def cmd_sync_range_attested(args: argparse.Namespace) -> int:
    try:
        if args.range_json == "-":
            document = json.loads(sys.stdin.read())
        else:
            document = json.loads(args.range_json)
    except (ValueError, TypeError) as exc:
        return _emit(400, {"error": f"invalid JSON range document: {exc}"})
    # Same range document as sync-range: {"anchor", "blocks"[, "tip"]}; a
    # GET /v1/chain/range page may be piped verbatim (its extra canonical/
    # next_height fields are ignored) and the tip is derived from the final
    # delivered block when omitted.
    if not isinstance(document, dict):
        return _emit(400, {"error": "range document must be a JSON object"})
    anchor = document.get("anchor")
    blocks = document.get("blocks")
    if not isinstance(anchor, dict) or not isinstance(blocks, list):
        return _emit(
            400, {"error": "range document must contain an anchor object and a blocks list"}
        )
    tip = document.get("tip")
    if tip is None and blocks:
        # Derive the closed tip summary from the final delivered block so a
        # plain range page (which carries no tip) can be pushed verbatim.
        last = blocks[-1]
        if isinstance(last, dict):
            anchor_height = anchor.get("height")
            length = (
                anchor_height + 1 + len(blocks)
                if isinstance(anchor_height, int) and not isinstance(anchor_height, bool)
                else None
            )
            tip = {
                "tip_hash": last.get("block_hash"),
                "height": last.get("height"),
                "length": length,
                "status": last.get("status"),
            }
    if not isinstance(tip, dict):
        return _emit(400, {"error": "range document must contain a tip object"})
    # The signature is over the canonical {domain, source, request_id,
    # expires_at, anchor, blocks, tip} message; the 64-lowercase-hex seed
    # signs the raw SHA-256 digest, producing a 128-lowercase-hex signature.
    signed = {
        "domain": "ledger-sync-range-v1",
        "source": args.source,
        "request_id": args.request_id,
        "expires_at": args.expires_at,
        "anchor": anchor,
        "blocks": blocks,
        "tip": tip,
    }
    message = json.dumps(
        signed, sort_keys=True, ensure_ascii=False, separators=(",", ":")
    ).encode("utf-8")
    signature = crypto.sign_message(
        args.signing_key, hashlib.sha256(message).digest()
    )
    if signature is None:
        return _emit(400, {"error": "signing key must be 64 lowercase hex characters"})
    payload = {
        "source": args.source,
        "request_id": args.request_id,
        "expires_at": args.expires_at,
        "anchor": anchor,
        "blocks": blocks,
        "tip": tip,
        "signature": signature,
    }
    status, body = _request(
        "POST", f"{args.base_url}/v1/forks/sync/range/attested", payload
    )
    return _emit(status, body)


def cmd_index(args: argparse.Namespace) -> int:
    filters = {
        "tx_id": args.tx_id,
        "account": args.account,
        "height": args.height,
